//! 📄️ Page nested changes admit every identity version before moving original row owners.
use crate::*;
use semio_s_artifact_layout_layout_model::{Page,Frame,Layer,PageOverride,LayoutRect};
use semio_framework_os_kernel::ApplyCapability;
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep}};
use super::{final_list::{FinalList,VacantRow},super::{chained_plan::{ChainedPlan,Address,Modification},positional_chain::PositionalChain,borrowed_lists::{BorrowedChain,BorrowedPositionalChain},keyed_plan::{Origin,PlanAdvance},setters::OwnedPatch}};
use std::mem::size_of;
use super::page_cache::{PageLayerCacheSource,PageCachePreparation};
struct CacheView<'a>{target:usize,indices:&'a [Vec<usize>;4],frames:&'a ChainedPlan,layers:&'a ChainedPlan,layer_sources:&'a [Option<Modification>],base:&'a Page,delta:&'a LayoutPagesDelta}
impl CacheView<'_>{fn frame(&self,i:usize)->&Frame{if self.indices[0].is_empty(){&self.base.frames[i]}else{let at=self.frames.origins().expect("admitted frame cache source")[i];match at.step{None=>&self.base.frames[at.row],Some(step)=>&self.delta.modified[self.indices[0][step]].patch.frames.inserted[at.row].row}}}}
impl PageLayerCacheSource for CacheView<'_>{fn identity(&self)->usize{self.target+1}fn frame_count(&self)->usize{if self.indices[0].is_empty(){self.base.frames.len()}else{self.frames.origins().expect("cache frame extent").len()}}fn frame_id(&self,i:usize)->&str{self.frame(i).id()}fn frame_layer_id(&self,i:usize)->&str{if let Some(Some(at))=self.layer_sources.get(i){self.delta.modified[self.indices[0][at.step]].patch.frames.modified[at.index].patch.layer_id.as_deref().expect("final authored cache layer")}else{self.frame(i).layer_id()}}fn layer_count(&self)->usize{if self.indices[1].is_empty(){self.base.layers.len()}else{self.layers.origins().expect("cache layer extent").len()}}fn layer_id(&self,i:usize)->&str{if self.indices[1].is_empty(){&self.base.layers[i].id}else{let at=self.layers.origins().expect("admitted cache layer")[i];match at.step{None=>&self.base.layers[at.row].id,Some(step)=>&self.delta.modified[self.indices[1][step]].patch.layers.inserted[at.row].row.id}}}}
fn frames(d:&LayoutPagesDelta,i:usize)->&PageFramesDelta{&d.modified[i].patch.frames}
fn layers(d:&LayoutPagesDelta,i:usize)->&PageLayersDelta{&d.modified[i].patch.layers}
fn overrides(d:&LayoutPagesDelta,i:usize)->&PageOverridesDelta{&d.modified[i].patch.overrides}
fn guides(d:&LayoutPagesDelta,i:usize)->&PageGuidesDelta{d.modified[i].patch.guides.as_ref().expect("selected authored guides")}
fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:256,depth:1,..Default::default()}}
fn paid()->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:256,..Default::default()}}
fn fault()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"Layout retained page stage is invalid")}
/// 🧳 Numeric provenance and typed nested movers retain all source and displaced owners.
pub struct PageWork{pub target:usize,pub origin:Origin,pub indices:[Vec<usize>;4],pub counts:[usize;4],frame_plan:ChainedPlan,layer_plan:ChainedPlan,override_plan:ChainedPlan,guide_plan:PositionalChain,frame_rows:FinalList<Frame>,layer_rows:FinalList<Layer>,override_rows:FinalList<PageOverride>,guide_rows:FinalList<LayoutRect>,layer_sources:Vec<Option<Modification>>,cache:PageCachePreparation,phase:u8,index:usize,field:usize,scan:usize,found:Option<usize>,commit_phase:u8,closing:bool}
impl PageWork{
 pub fn new(target:usize,origin:Origin)->Self{Self{target,origin,indices:Default::default(),counts:[0;4],frame_plan:ChainedPlan::new(),layer_plan:ChainedPlan::new(),override_plan:ChainedPlan::new(),guide_plan:PositionalChain::new(),frame_rows:FinalList::new(),layer_rows:FinalList::new(),override_rows:FinalList::new(),guide_rows:FinalList::new(),layer_sources:Vec::new(),cache:PageCachePreparation::new(),phase:0,index:0,field:0,scan:0,found:None,commit_phase:0,closing:false}}
 pub fn selected(p:&PagePatch,k:usize)->bool{match k{0=>!p.frames.removed.is_empty()||!p.frames.inserted.is_empty()||!p.frames.moved.is_empty()||!p.frames.modified.is_empty(),1=>!p.layers.removed.is_empty()||!p.layers.inserted.is_empty()||!p.layers.moved.is_empty()||!p.layers.modified.is_empty(),2=>!p.overrides.removed.is_empty()||!p.overrides.inserted.is_empty()||!p.overrides.moved.is_empty(),3=>p.guides.is_some(),_=>false}}
 pub fn frame_count(&self,base:&Page)->usize{if self.indices[0].is_empty(){base.frames.len()}else{self.frame_plan.origins().expect("admitted frame origins").len()}}
 pub fn layer_count(&self,base:&Page)->usize{if self.indices[1].is_empty(){base.layers.len()}else{self.layer_plan.origins().expect("admitted layer origins").len()}}
 fn source_frame<'a>(&self,base:&'a Page,d:&'a LayoutPagesDelta,at:Address)->&'a Frame{match at.step{None=>&base.frames[at.row],Some(step)=>&d.modified[self.indices[0][step]].patch.frames.inserted[at.row].row}}
 pub fn frame<'a>(&self,base:&'a Page,d:&'a LayoutPagesDelta,index:usize)->&'a Frame{if self.indices[0].is_empty(){&base.frames[index]}else{self.source_frame(base,d,self.frame_plan.origins().expect("admitted frames")[index])}}
 pub fn frame_layer_id<'a>(&self,base:&'a Page,d:&'a LayoutPagesDelta,index:usize)->&'a str{if let Some(Some(at))=self.layer_sources.get(index){d.modified[self.indices[0][at.step]].patch.frames.modified[at.index].patch.layer_id.as_deref().expect("authored final frame layer")}else{self.frame(base,d,index).layer_id()}}
 pub fn layer<'a>(&self,base:&'a Page,d:&'a LayoutPagesDelta,index:usize)->&'a Layer{if self.indices[1].is_empty(){&base.layers[index]}else{let at=self.layer_plan.origins().expect("admitted layers")[index];match at.step{None=>&base.layers[at.row],Some(step)=>&d.modified[self.indices[1][step]].patch.layers.inserted[at.row].row}}}
 fn cache_view<'a>(&'a self,base:&'a Page,d:&'a LayoutPagesDelta)->CacheView<'a>{CacheView{target:self.target,indices:&self.indices,frames:&self.frame_plan,layers:&self.layer_plan,layer_sources:&self.layer_sources,base,delta:d}}
 fn cache_needed(&self)->bool{true}
 pub fn preflight_demand(&self,base:&Page,d:&LayoutPagesDelta)->Result<RetirementDemand,ValueError>{Ok(match self.phase{
  0=>if self.indices[0].is_empty(){fixed()}else{self.frame_plan.demand(&BorrowedChain{held:&base.frames,indices:&self.indices[0],owner:d,delta:frames})?},
  1=>if self.indices[1].is_empty(){fixed()}else{self.layer_plan.demand(&BorrowedChain{held:&base.layers,indices:&self.indices[1],owner:d,delta:layers})?},
  2=>if self.indices[2].is_empty(){fixed()}else{self.override_plan.demand(&BorrowedChain{held:&base.overrides,indices:&self.indices[2],owner:d,delta:overrides})?},
  3=>if self.indices[3].is_empty(){fixed()}else{self.guide_plan.demand(&BorrowedPositionalChain{held_len:base.guides.len(),indices:&self.indices[3],owner:d,delta:guides})?},
  4=>RetirementDemand{capacity_bytes:if self.indices[0].is_empty(){0}else{self.frame_count(base)*size_of::<Option<Modification>>()},..fixed()},5|6=>fixed(),
  7=>if self.indices[0].is_empty(){fixed()}else{self.frame_rows.preflight_demand(base.frames.len(),self.frame_plan.origins().ok_or_else(fault)?)?},
  8=>if self.indices[1].is_empty(){fixed()}else{self.layer_rows.preflight_demand(base.layers.len(),self.layer_plan.origins().ok_or_else(fault)?)?},
  9=>if self.indices[2].is_empty(){fixed()}else{self.override_rows.preflight_demand(base.overrides.len(),self.override_plan.origins().ok_or_else(fault)?)?},
  10=>if self.indices[3].is_empty(){fixed()}else{self.guide_rows.preflight_demand(base.guides.len(),self.guide_plan.origins().ok_or_else(fault)?)?},11=>if self.cache_needed(){self.cache.demand(&self.cache_view(base,d))?}else{fixed()},12=>fixed(),_=>return Err(fault())})}
 pub fn preflight(&mut self,base:&Page,d:&LayoutPagesDelta,g:RetainedCloneGrant)->Result<PlanAdvance,ValueError>{let demand=self.preflight_demand(base,d)?;let mut out=PlanAdvance{done:false,error:None,progress:Default::default()};if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,demand){return Ok(out)}out.progress=paid();match self.phase{
  0..=3=>{if self.indices[self.phase as usize].is_empty(){self.phase+=1}else{out=match self.phase{0=>self.frame_plan.advance(&BorrowedChain{held:&base.frames,indices:&self.indices[0],owner:d,delta:frames},g)?,1=>self.layer_plan.advance(&BorrowedChain{held:&base.layers,indices:&self.indices[1],owner:d,delta:layers},g)?,2=>self.override_plan.advance(&BorrowedChain{held:&base.overrides,indices:&self.indices[2],owner:d,delta:overrides},g)?,3=>self.guide_plan.advance(&BorrowedPositionalChain{held_len:base.guides.len(),indices:&self.indices[3],owner:d,delta:guides},g)?,_=>unreachable!()};if out.done{self.phase+=1;out.done=false}}},
  4=>{let n=if self.indices[0].is_empty(){0}else{self.frame_count(base)};let reserved=self.layer_sources.try_reserve_exact(n);out.progress.retained_capacity_bytes=self.layer_sources.capacity()*size_of::<Option<Modification>>();if reserved.is_err()||out.progress.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(fault().with_retained_progress(out.progress))}self.phase=5},
  5=>if self.layer_sources.len()==if self.indices[0].is_empty(){0}else{self.frame_count(base)}{self.phase=6}else{self.layer_sources.push(None)},
  6=>{let mods=self.frame_plan.modifications().unwrap_or(&[]);if self.index==mods.len(){self.phase=7;self.index=0;self.field=0;self.scan=0}else{let at=mods[self.index];let patch=&d.modified[self.indices[0][at.step]].patch.frames.modified[at.index].patch;if self.field<FramePatch::FIELD_COUNT{if !patch.admissible(self.source_frame(base,d,at.target),self.field){out.error=Some("layout.frame.patch-kind");return Ok(out)}self.field+=1}else{let origins=self.frame_plan.origins().expect("admitted frame identity versions");if self.scan==origins.len(){self.index+=1;self.field=0;self.scan=0}else{if origins[self.scan]==at.target&&patch.layer_id.is_some(){self.layer_sources[self.scan]=Some(at)}self.scan+=1}}}},
  7..=10=>{let k=(self.phase-7)as usize;let step=if self.indices[k].is_empty(){RetainedCloneStep::Complete(paid())}else{match k{0=>self.frame_rows.preflight(base.frames.len(),self.frame_plan.origins().ok_or_else(fault)?,g)?,1=>self.layer_rows.preflight(base.layers.len(),self.layer_plan.origins().ok_or_else(fault)?,g)?,2=>self.override_rows.preflight(base.overrides.len(),self.override_plan.origins().ok_or_else(fault)?,g)?,3=>self.guide_rows.preflight(base.guides.len(),self.guide_plan.origins().ok_or_else(fault)?,g)?,_=>unreachable!()}};out.progress=step.progress();if matches!(step,RetainedCloneStep::Complete(_)){self.phase+=1}},
  11=>{if self.cache_needed(){let source=CacheView{target:self.target,indices:&self.indices,frames:&self.frame_plan,layers:&self.layer_plan,layer_sources:&self.layer_sources,base,delta:d};let step=self.cache.advance(&source,g)?;out.progress=step.progress();if self.cache.is_ready(){self.phase=12}}else{self.phase=12}},12=>out.done=true,_=>return Err(fault())}Ok(out)}
 pub fn commit_demand(&self,modified:&[LayoutPagesModification])->Result<RetirementDemand,ValueError>{Ok(match self.commit_phase{0=>if self.indices[3].is_empty(){fixed()}else{self.guide_rows.commit_demand()?},1=>if self.indices[2].is_empty(){fixed()}else{self.override_rows.commit_demand()?},2=>if self.indices[0].is_empty(){fixed()}else{self.frame_rows.commit_demand()?},3=>if self.indices[1].is_empty(){fixed()}else{self.layer_rows.commit_demand()?},4|5=>if let Some(target)=self.found{let _=target;if self.commit_phase==4{let at=self.frame_plan.modifications().ok_or_else(fault)?[self.index];modified[self.indices[0][at.step]].patch.frames.modified[at.index].patch.field_demand(self.field)?}else{let at=self.layer_plan.modifications().ok_or_else(fault)?[self.index];modified[self.indices[1][at.step]].patch.layers.modified[at.index].patch.field_demand(self.field)?}}else{fixed()},6=>if self.cache_needed(){self.cache.install_demand()?}else{fixed()},7=>fixed(),_=>return Err(fault())})}
 pub fn commit(&mut self,base:&mut Page,modified:&mut [LayoutPagesModification],g:RetainedCloneGrant,capability:ApplyCapability)->Result<RetainedCloneStep,ValueError>{let demand=self.commit_demand(modified)?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,demand){return Ok(RetainedCloneStep::Progress(Default::default()))}let mut p=paid();match self.commit_phase{
  0..=3=>{let k=match self.commit_phase{0=>3,1=>2,2=>0,_=>1};let indices=&self.indices[k];let step=if indices.is_empty(){RetainedCloneStep::Complete(paid())}else{match k{
   0=>self.frame_rows.commit(&mut base.frames,self.frame_plan.origins().ok_or_else(fault)?,g,capability,|at|{let row=&mut modified[indices[at.step.unwrap()]].patch.frames.inserted[at.row].row;std::mem::replace(row,Frame::vacant())})?,
   1=>self.layer_rows.commit(&mut base.layers,self.layer_plan.origins().ok_or_else(fault)?,g,capability,|at|{let row=&mut modified[indices[at.step.unwrap()]].patch.layers.inserted[at.row].row;std::mem::replace(row,Layer::vacant())})?,
   2=>self.override_rows.commit(&mut base.overrides,self.override_plan.origins().ok_or_else(fault)?,g,capability,|at|{let row=&mut modified[indices[at.step.unwrap()]].patch.overrides.inserted[at.row].row;std::mem::replace(row,PageOverride::vacant())})?,
   3=>self.guide_rows.commit(&mut base.guides,self.guide_plan.origins().ok_or_else(fault)?,g,capability,|at|{let row=&mut modified[indices[at.step.unwrap()]].patch.guides.as_mut().expect("owned guides").rows[at.row].guide;std::mem::replace(row,LayoutRect::vacant())})?,_=>unreachable!()}};p=step.progress();if matches!(step,RetainedCloneStep::Complete(_)){self.commit_phase+=1;self.index=0;self.scan=0;self.field=0}},
  4|5=>{let (mods,origins)=if self.commit_phase==4{(self.frame_plan.modifications().unwrap_or(&[]),self.frame_plan.origins().unwrap_or(&[]))}else{(self.layer_plan.modifications().unwrap_or(&[]),self.layer_plan.origins().unwrap_or(&[]))};if self.index==mods.len(){self.commit_phase+=1;self.index=0;self.scan=0;self.field=0;self.found=None}else{let at=mods[self.index];if let Some(target)=self.found{let max=if self.commit_phase==4{FramePatch::FIELD_COUNT}else{LayerPatch::FIELD_COUNT};let step=if self.commit_phase==4{modified[self.indices[0][at.step]].patch.frames.modified[at.index].patch.exchange_field(&mut base.frames[target],self.field,g,capability)?}else{modified[self.indices[1][at.step]].patch.layers.modified[at.index].patch.exchange_field(&mut base.layers[target],self.field,g,capability)?};p=step.progress();self.field+=1;if self.field==max{self.index+=1;self.scan=0;self.field=0;self.found=None}}else if self.scan==origins.len(){self.index+=1;self.scan=0}else{if origins[self.scan]==at.target{self.found=Some(self.scan)}self.scan+=1}}},6=>{if self.cache_needed(){let step=self.cache.install(base,g,capability)?;p=step.progress();if matches!(step,RetainedCloneStep::Complete(_)){self.commit_phase=7}}else{self.commit_phase=7}},7=>return Ok(RetainedCloneStep::Complete(p)),_=>return Err(fault())}Ok(RetainedCloneStep::Progress(p))}
 pub fn begin_close(&mut self){self.closing=true;self.frame_plan.begin_close();self.layer_plan.begin_close();self.override_plan.begin_close();self.guide_plan.begin_close();self.frame_rows.begin_close();self.layer_rows.begin_close();self.override_rows.begin_close();self.guide_rows.begin_close();self.cache.begin_close()}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.cache.terminal_is_empty(){return self.cache.close_demand(body)}if !self.frame_rows.terminal_is_empty(){return self.frame_rows.close_demand(body)}if !self.layer_rows.terminal_is_empty(){return self.layer_rows.close_demand(body)}if !self.override_rows.terminal_is_empty(){return self.override_rows.close_demand(body)}if !self.guide_rows.terminal_is_empty(){return self.guide_rows.close_demand(body)}if !self.frame_plan.terminal_is_empty(){return Ok(self.frame_plan.close_demand())}if !self.layer_plan.terminal_is_empty(){return Ok(self.layer_plan.close_demand())}if !self.override_plan.terminal_is_empty(){return Ok(self.override_plan.close_demand())}if !self.guide_plan.terminal_is_empty(){return Ok(self.guide_plan.close_demand())}let release=if self.layer_sources.is_empty()&&self.indices.iter().all(Vec::is_empty){self.layer_sources.capacity()*size_of::<Option<Modification>>()+self.indices.iter().map(|v|v.capacity()*size_of::<usize>()).sum::<usize>()}else{0};Ok(RetirementDemand{release_bytes:release,..fixed()})}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(fault())}let d=self.close_demand(g.maximum_copy_bytes)?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.cache.terminal_is_empty(){return self.cache.close_step(g).map(|step|RetainedCloneStep::Progress(step.progress()))}if !self.frame_rows.terminal_is_empty(){return self.frame_rows.close_step(g).map(|step|RetainedCloneStep::Progress(step.progress()))}if !self.layer_rows.terminal_is_empty(){return self.layer_rows.close_step(g).map(|step|RetainedCloneStep::Progress(step.progress()))}if !self.override_rows.terminal_is_empty(){return self.override_rows.close_step(g).map(|step|RetainedCloneStep::Progress(step.progress()))}if !self.guide_rows.terminal_is_empty(){return self.guide_rows.close_step(g).map(|step|RetainedCloneStep::Progress(step.progress()))}if !self.frame_plan.terminal_is_empty(){return self.frame_plan.close_step(g).map(RetainedCloneStep::Progress)}if !self.layer_plan.terminal_is_empty(){return self.layer_plan.close_step(g).map(RetainedCloneStep::Progress)}if !self.override_plan.terminal_is_empty(){return self.override_plan.close_step(g).map(RetainedCloneStep::Progress)}if !self.guide_plan.terminal_is_empty(){return self.guide_plan.close_step(g).map(RetainedCloneStep::Progress)}if self.layer_sources.pop().is_some(){return Ok(RetainedCloneStep::Progress(paid()))}for rows in &mut self.indices{if rows.pop().is_some(){return Ok(RetainedCloneStep::Progress(paid()))}}self.layer_sources=Vec::new();self.indices=Default::default();Ok(RetainedCloneStep::Complete(RetainedCloneProgress{released_bytes:d.release_bytes,..paid()}))}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.cache.terminal_is_empty()&&self.frame_rows.terminal_is_empty()&&self.layer_rows.terminal_is_empty()&&self.override_rows.terminal_is_empty()&&self.guide_rows.terminal_is_empty()&&self.frame_plan.terminal_is_empty()&&self.layer_plan.terminal_is_empty()&&self.override_plan.terminal_is_empty()&&self.guide_plan.terminal_is_empty()&&self.layer_sources.is_empty()&&self.layer_sources.capacity()==0&&self.indices.iter().all(|rows|rows.is_empty()&&rows.capacity()==0)}
}
impl Drop for PageWork{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"page nested originals require funded close")}}

impl PageWork{
 pub fn final_frame_origin(&self,index:usize)->Address{if self.indices[0].is_empty(){Address{step:None,row:index}}else{self.frame_plan.origins().expect("admitted final frame view")[index]}}
 pub fn final_frame_modifications(&self)->&[Modification]{self.frame_plan.modifications().unwrap_or(&[])}
 pub fn final_frame_patch<'a>(&self,d:&'a LayoutPagesDelta,at:Modification)->&'a FramePatch{&d.modified[self.indices[0][at.step]].patch.frames.modified[at.index].patch}
 pub fn final_layer_count(&self,base:&Page)->usize{self.layer_count(base)}
 pub fn final_override_count(&self,base:&Page)->usize{if self.indices[2].is_empty(){base.overrides.len()}else{self.override_plan.origins().expect("admitted final overrides").len()}}
 pub fn final_override<'a>(&self,base:&'a Page,d:&'a LayoutPagesDelta,index:usize)->&'a PageOverride{if self.indices[2].is_empty(){&base.overrides[index]}else{let at=self.override_plan.origins().expect("admitted final override view")[index];match at.step{None=>&base.overrides[at.row],Some(step)=>&d.modified[self.indices[2][step]].patch.overrides.inserted[at.row].row}}}
 pub fn final_guide_count(&self,base:&Page)->usize{if self.indices[3].is_empty(){base.guides.len()}else{self.guide_plan.origins().expect("admitted final guides").len()}}
 pub fn final_guide<'a>(&self,base:&'a Page,d:&'a LayoutPagesDelta,index:usize)->&'a LayoutRect{if self.indices[3].is_empty(){&base.guides[index]}else{let at=self.guide_plan.origins().expect("admitted final guide view")[index];match at.step{None=>&base.guides[at.row],Some(step)=>&d.modified[self.indices[3][step]].patch.guides.as_ref().expect("original final guide delta").rows[at.row].guide}}}
 pub fn final_cached_layer_ids<'a>(&'a self,base:&'a Page)->Result<&'a [String],ValueError>{if self.cache_needed(){self.cache.prepared_layer_ids()}else{Ok(&base.layer_ids)}}
 pub fn final_cached_objects<'a>(&'a self,base:&'a Page,layer:usize)->Result<&'a [String],ValueError>{if self.cache_needed(){self.cache.prepared_objects(layer)}else{Ok(&base.layers[layer].object_ids)}}
}
